  {notesMenu&&<div ref={notesPanel} className="notes-switcher glass-window" role="menu" aria-label="Notes windows" style={{left:notesPosition.left,top:notesPosition.top,'--panel-origin':notesPosition.side==='below'?'top':'bottom'}} onPointerDown={e=>e.stopPropagation()}><div className="switcher-heading">NOTES WINDOWS</div>{noteWindows.map(w=><button key={w.id} role="menuitem" onClick={()=>{setNotesMenu(false);focus(w.id)}}><AppIcon type={w.type} size={15}/><span>{w.type==='library'?'All notes':ws.notes.find(n=>n.id===w.noteId)?.title||'Untitled note'}</span><small>{w.minimized?'Minimized':w.id===active?'Active':''}</small></button>)}</div>}
